internal enum AccountStateTag: int {
    SignedOut,
    SignedIn,
    Offline
}

class FfiConverterTypeAccountStateTag: FfiConverterRustBuffer<AccountStateTag> {
    public static FfiConverterTypeAccountStateTag INSTANCE = new FfiConverterTypeAccountStateTag();

    public override AccountStateTag Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1: return AccountStateTag.SignedOut;
            case 2: return AccountStateTag.SignedIn;
            case 3: return AccountStateTag.Offline;
            default: throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeAccountStateTag.Read()", value));
        }
    }

    public override int AllocationSize(AccountStateTag value) {
        return 4;
    }

    public override void Write(AccountStateTag value, BigEndianStream stream) {
        switch (value) {
            case AccountStateTag.SignedOut: stream.WriteInt(1); break;
            case AccountStateTag.SignedIn: stream.WriteInt(2); break;
            case AccountStateTag.Offline: stream.WriteInt(3); break;
            default: throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeAccountStateTag.Write()", value));
        }
    }
}







internal record CellEdit {
    
    public record Text (
        string TextValue
    ) : CellEdit {}
    
    public record Null: CellEdit {}
    
    
    public record Default: CellEdit {}
    
    

    
}

class FfiConverterTypeCellEdit : FfiConverterRustBuffer<CellEdit>{
    public static FfiConverterRustBuffer<CellEdit> INSTANCE = new FfiConverterTypeCellEdit();

    public override CellEdit Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new CellEdit.Text(
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 2:
                return new CellEdit.Null(
                );
            case 3:
                return new CellEdit.Default(
                );
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeCellEdit.Read()", value));
        }
    }

    public override int AllocationSize(CellEdit value) {
        switch (value) {
            case CellEdit.Text variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.TextValue);
            case CellEdit.Null variant_value:
                return 4;
            case CellEdit.Default variant_value:
                return 4;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeCellEdit.AllocationSize()", value));
        }
    }

    public override void Write(CellEdit value, BigEndianStream stream) {
        switch (value) {
            case CellEdit.Text variant_value:
                stream.WriteInt(1);
                FfiConverterString.INSTANCE.Write(variant_value.TextValue, stream);
                break;
            case CellEdit.Null variant_value:
                stream.WriteInt(2);
                break;
            case CellEdit.Default variant_value:
                stream.WriteInt(3);
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeCellEdit.Write()", value));
        }
    }
}







