/// <summary>
/// Why a call produced no value. A cancel is its own variant, so a
/// binding can turn it into its language's cancellation.
/// </summary>
internal class CoreException: UniffiException {
    CoreException() : base() {}
    CoreException(String @Message) : base(@Message) {}

    // Each variant is a nested class
    
    public class Cancelled : CoreException {
        public Cancelled() : base() {}
    }
    
    
    
    public class Failed : CoreException {
        // Members
        public BoxedErrorInfo @info;

        // Constructor
        public Failed(
                BoxedErrorInfo @info) : base(
                "@info" + "=" + @info) {

            this.@info = @info;
        }
    }
    

    
}

class FfiConverterTypeCoreError : FfiConverterRustBuffer<CoreException>, CallStatusErrorHandler<CoreException> {
    public static FfiConverterTypeCoreError INSTANCE = new FfiConverterTypeCoreError();

    public override CoreException Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new CoreException.Cancelled();
            case 2:
                return new CoreException.Failed(
                    FfiConverterTypeBoxedErrorInfo.INSTANCE.Read(stream));
            default:
