    // Each variant is a nested class
    
    
    public class Unavailable : HostSecretException {
        // Members
        public string @detail;

        // Constructor
        public Unavailable(
                string @detail) : base(
                "@detail" + "=" + @detail) {

            this.@detail = @detail;
        }
    }
    
    public class Locked : HostSecretException {
        public Locked() : base() {}
    }
    
    
    public class Dismissed : HostSecretException {
        public Dismissed() : base() {}
    }
    
    
    
    public class Failed : HostSecretException {
        // Members
        public string @detail;

        // Constructor
        public Failed(
                string @detail) : base(
                "@detail" + "=" + @detail) {

            this.@detail = @detail;
        }
    }
    

    
}

class FfiConverterTypeHostSecretError : FfiConverterRustBuffer<HostSecretException>, CallStatusErrorHandler<HostSecretException> {
    public static FfiConverterTypeHostSecretError INSTANCE = new FfiConverterTypeHostSecretError();

    public override HostSecretException Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new HostSecretException.Unavailable(
                    FfiConverterString.INSTANCE.Read(stream));
            case 2:
                return new HostSecretException.Locked();
            case 3:
                return new HostSecretException.Dismissed();
            case 4:
                return new HostSecretException.Failed(
                    FfiConverterString.INSTANCE.Read(stream));
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeHostSecretError.Read()", value));
        }
    }

    public override int AllocationSize(HostSecretException value) {
        switch (value) {

            case HostSecretException.Unavailable variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@detail);

            case HostSecretException.Locked variant_value:
                return 4;

            case HostSecretException.Dismissed variant_value:
                return 4;

            case HostSecretException.Failed variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@detail);
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeHostSecretError.AllocationSize()", value));
        }
    }

    public override void Write(HostSecretException value, BigEndianStream stream) {
        switch (value) {
            case HostSecretException.Unavailable variant_value:
                stream.WriteInt(1);
                FfiConverterString.INSTANCE.Write(variant_value.@detail, stream);
                break;
            case HostSecretException.Locked variant_value:
                stream.WriteInt(2);
                break;
            case HostSecretException.Dismissed variant_value:
                stream.WriteInt(3);
                break;
            case HostSecretException.Failed variant_value:
                stream.WriteInt(4);
                FfiConverterString.INSTANCE.Write(variant_value.@detail, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeHostSecretError.Write()", value));
        }
    }
}





