    /// </summary>
    Date = 11,
    /// <summary>
    /// `raw` is microseconds from midnight, negative or past a day for
    /// a duration.
    /// </summary>
    Time = 12,
    /// <summary>
    /// `raw` is microseconds from midnight, before the offset.
    /// </summary>
    TimeWithOffset = 13,
    /// <summary>
